  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Suffering and Trust: Job$j$, $j${"readings": [{"title": "Job 1 (King James Version)", "url": "/portal/bible/Job/1"}, {"title": "Job 19 (King James Version)", "url": "/portal/bible/Job/19"}, {"title": "Job 42 (King James Version)", "url": "/portal/bible/Job/42"}], "body": "Read Job 1, Job 19 and Job 42 in the King James Version. Then read this lesson.\n\nJob is the oldest story of suffering in the Bible. Job was a good man who lost his children, his wealth and his health in a short time. Three friends came to comfort him, but they argued that Job must have sinned to deserve it. Job insisted that he was honest, and he asked hard questions of God. In the end God spoke to Job out of a whirlwind, not to explain every detail, but to remind Job who He is. Job trusted God, God restored him, and the friends were corrected.\n\nThe book teaches that suffering is not always punishment, and that God is wise and in control even when we do not understand.\n\nKey words: suffering, integrity, patience, redeemer, restoration.\n\nYour task: (1) List three things Job lost in chapter 1. (2) Say what Job answered in Job 1:21. (3) Explain what the friends got wrong.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 3. The books in this unit are called the books of poetry and wisdom. They are different from the history we have been reading. They are made of prayers, songs, sayings and speeches. We begin with Job, the book that asks one of the hardest questions people ever ask. Why do good people suffer?\n\nThe book opens with a description of Job. Job 1 says that he was perfect and upright, and one that feared God, and eschewed evil. He was also the greatest man of the east. Then in one day Job lost his oxen, his donkeys, his sheep, his servants and, worst of all, his ten children. Soon after that he lost his health.\n\nListen to Job's first response. He fell down and worshipped, and said, Naked came I out of my mother's womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD. Job did not understand, but he still blessed God.\n\nThree friends came to sit with him. At first they were a comfort because they sat in silence. But then they began to talk. They said that suffering always comes from sin, so Job must have done something wrong. Job knew that was not true, and he told them so. This is one of the main lessons of the book. We must be careful about explaining other people's pain. Sometimes the best help is to stay close and say little.\n\nIn the middle of his pain Job said something that shines like a light. Job 19:25 says, For I know that my redeemer liveth, and that he shall stand at the latter day upon the earth. Even in his darkness, Job held on to the hope that God would make everything right.\n\nAt last God answered. He spoke from a whirlwind and asked Job questions about creation. God did not give Job a list of reasons. He showed Job His power and wisdom, and Job humbled himself. God restored Job and gave him twice as much as before, and He told the friends to ask Job to pray for them.\n\nYour task is to list three things Job lost, tell what Job said in Job 1:21, and explain what the friends got wrong. Then take the four question check.\n\nGod is still God when we do not have all the answers. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Suffering and Trust: Job$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 The Prayer Book of Israel: Psalms$j$, $j${"readings": [{"title": "Psalm 1 (King James Version)", "url": "/portal/bible/Psalms/1"}, {"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}, {"title": "Psalm 23 (King James Version)", "url": "/portal/bible/Psalms/23"}, {"title": "Psalm 100 (King James Version)", "url": "/portal/bible/Psalms/100"}], "body": "Read Psalm 1, Psalm 19, Psalm 23 and Psalm 100 in the King James Version. Then read this lesson.\n\nThe book of Psalms has 150 songs and prayers. David wrote about half of them. Others were written by Asaph, the sons of Korah, Solomon, Moses and unnamed writers. The Psalms were the songbook for Israel's worship. They include praise, thanksgiving, prayers for help, confession of sin, and psalms of trust. Many of them are written in Hebrew poetry, where a line is repeated or answered by a second line with the same idea. This is called parallelism. The Psalms help us talk to God honestly about every season of life.\n\nKey words: praise, lament, trust, parallelism, worship.\n\nYour task: (1) Tell how Psalm 1 describes a blessed person. (2) Write Psalm 23:1 from memory or from your Bible. (3) Name one kind of psalm and say when you might pray it.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "The book of Psalms is the longest book in the Bible. It has one hundred and fifty chapters, and each one is a song or a prayer. It was the songbook of Israel and it has been the prayer book of God's people ever since.\n\nPsalms was written over many centuries. David wrote about half of them. Others came from Asaph, the sons of Korah, Solomon and even Moses. The Psalms are honest. There are psalms of joy and psalms of tears. There are psalms of praise, psalms of thanksgiving, psalms that cry out for help, psalms that confess sin and psalms that simply trust.\n\nHebrew poetry does not depend on rhyme the way English poetry often does. It depends on balance. A line is followed by a second line that repeats it, completes it or contrasts with it. Psalm 19:1 says, The heavens declare the glory of God; and the firmament sheweth his handywork. The first line and the second line say almost the same thing in different words. This pattern is called parallelism, and once you see it, you will find it everywhere in the book.\n\nPsalm 1 opens the book and sets two paths side by side. The blessed man does not follow the counsel of the ungodly. Instead, as Psalm 1:2 says, his delight is in the law of the LORD; and in his law doth he meditate day and night. The person who lives in God's word is like a tree planted by the rivers of water.\n\nThe most loved psalm is Psalm 23. It begins, The LORD is my shepherd; I shall not want. David was a shepherd himself, so he knew what a shepherd does. He leads, feeds, protects and stays with his sheep, even in the valley of the shadow of death. Whenever you feel afraid or alone, this psalm can be your prayer.\n\nPsalm 100 is a psalm of praise. Verse 4 says, Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name. And Psalm 119, the longest chapter in the Bible, praises God's word. Verse 105 says, Thy word is a lamp unto my feet, and a light unto my path.\n\nYour task is to tell how Psalm 1 describes a blessed person, write Psalm 23:1, and name one kind of psalm and when you might pray it. Then take the four question check.\n\nWhen you do not know what to say to God, open the Psalms. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 The Prayer Book of Israel: Psalms$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Wisdom for Daily Life: Proverbs$j$, $j${"readings": [{"title": "Proverbs 1 (King James Version)", "url": "/portal/bible/Proverbs/1"}, {"title": "Proverbs 3 (King James Version)", "url": "/portal/bible/Proverbs/3"}, {"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}, {"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Read Proverbs 1, 3, 15 and 22 in the King James Version. Then read this lesson.\n\nProverbs is a collection of short, wise sayings, mostly written by Solomon. A proverb states a general truth that is usually right, not a promise that is always right. The book is written as a father speaking to his son. It gives practical guidance on speech, friends, work, money, anger, discipline and the choices that shape a life. The theme is stated in Proverbs 1:7: the fear of the LORD is the beginning of knowledge. Wisdom is not just knowing facts. It is knowing how to live well before God.\n\nKey words: wisdom, fear of the LORD, folly, discipline, speech.\n\nYour task: (1) Write Proverbs 1:7 in your own words. (2) Pick one proverb from chapters 3, 15 or 22 and say how it could help a student. (3) Tell the difference between a wise person and a fool in Proverbs.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Proverbs is the book of wisdom. Most of it was written by King Solomon, the man who asked God for an understanding heart. The book is written like a father talking to his son, and it covers everyday life: how to speak, how to choose friends, how to work, how to handle money and how to control anger.\n\nThe theme of the whole book is found in Proverbs 1:7. The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction. The fear of the LORD means respect, reverence and obedience. Real wisdom starts with God. A person can learn many facts and still be foolish if they leave God out.\n\nA proverb is a short saying that states a general truth. It is usually right, but it is not a promise in every case. For example, Proverbs 22:6 says, Train up a child in the way he should go: and when he is old, he will not depart from it. It teaches that early training matters and has a lasting effect. It does not promise that every child will turn out the same.\n\nProverbs pays special attention to words. Proverbs 15:1 says, A soft answer turneth away wrath: but grievous words stir up anger. How you answer can calm a fight or start one. Students deal with this every day, in the hallway, in a group chat and at home.\n\nProverbs also teaches trust. Proverbs 3:5 and 6 say, Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths. When you face a decision about school, friends or your future, start there. Bring God into every part of the decision.\n\nThroughout the book the wise person and the fool are put side by side. The wise person listens, learns and plans. The fool is quick to speak, slow to listen and unwilling to be corrected. Proverbs invites us to choose wisdom while we are young.\n\nYour task is to put Proverbs 1:7 in your own words, choose one proverb and tell how it helps a student, and tell the difference between a wise person and a fool. Then take the four question check.\n\nWisdom begins with God and shows up in the small choices of every day. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Wisdom for Daily Life: Proverbs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Seasons and Love: Ecclesiastes and Song of Solomon$j$, $j${"readings": [{"title": "Ecclesiastes 1 (King James Version)", "url": "/portal/bible/Ecclesiastes/1"}, {"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}, {"title": "Ecclesiastes 12 (King James Version)", "url": "/portal/bible/Ecclesiastes/12"}, {"title": "Song of Solomon 8 (King James Version)", "url": "/portal/bible/SongofSolomon/8"}], "body": "Read Ecclesiastes 1:1 to 11, Ecclesiastes 3:1 to 8, Ecclesiastes 12 and Song of Solomon 8 in the King James Version. Then read this lesson.\n\nEcclesiastes is the reflection of a wise man, called the Preacher, who tried to find meaning in wealth, pleasure, work and learning. He found that apart from God everything is vanity, a word that means a puff of breath. Yet he also taught that life has a season for every purpose and that God's gifts are to be enjoyed. The book ends by giving the conclusion of the whole matter: fear God and keep His commandments.\n\nThe Song of Solomon is a love poem between a husband and wife. It celebrates marriage and faithful love as a gift from God. Many readers also see in it a picture of God's love for His people.\n\nKey words: vanity, season, meaning, conclusion, covenant love.\n\nYour task: (1) Say what the Preacher found when he sought meaning without God. (2) Write the conclusion of Ecclesiastes 12:13 in your own words. (3) Tell what Song of Solomon celebrates.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Today we finish the books of poetry and wisdom with two short but very different books. The first is Ecclesiastes. The second is the Song of Solomon.\n\nEcclesiastes is written by a man who calls himself the Preacher. He had wealth, wisdom and power. He tried everything to find meaning in life: learning, pleasure, great building projects, riches and hard work. Over and over he came to the same conclusion. Ecclesiastes 1:2 begins, Vanity of vanities, saith the Preacher. The word vanity means something like a breath or a vapor. It is here for a moment and then gone. He is saying that if life is lived only for this world, it will not satisfy.\n\nBut the book also holds some real encouragement. Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. There is a time to be born and a time to die, a time to weep and a time to laugh, a time to be silent and a time to speak. God has ordered our lives in seasons, and we can trust Him in each one.\n\nThe Preacher also tells young people something practical. Ecclesiastes 12:1 says, Remember now thy Creator in the days of thy youth. Do not wait until later in life to put God first.\n\nThe book ends with a clear conclusion. Ecclesiastes 12:13 says, Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man. After all the searching, the answer is simple. Honor God and obey Him.\n\nThe Song of Solomon is different. It is a love poem between a bride and bridegroom, written in beautiful, picture filled language. It shows that God created marriage and that faithful, pure love is His gift. In the last chapter, the bride says that love is strong, and Song of Solomon 8:7 says, Many waters cannot quench love, neither can the floods drown it. Many Christians through the centuries have also read this song as a picture of the love between God and His people.\n\nYour task is to say what the Preacher found, write Ecclesiastes 12:13 in your own words, and tell what the Song of Solomon celebrates. Then take the four question check and the Unit 3 quiz.\n\nWhen life is built on God, it has meaning in every season. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Seasons and Love: Ecclesiastes and Song of Solomon$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: A Psalm of My Own$j$, $j${"prompt": "Read Psalm 23 and Psalm 100 again. Then write a short psalm of your own of 8 to 12 lines. It can be a prayer of thanks, trust or request. Use at least two lines that show parallelism, where the second line repeats or completes the first. Then write two or three sentences that explain which psalm from this unit inspired you and why. Quote at least one verse from the King James Version.", "rubric": "Total 100. Psalm of 8 to 12 lines with honest, reverent content: 30. At least two lines that show parallelism: 20. Explanation of the psalm that inspired you, with a quoted King James Version verse: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: A Psalm of My Own$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: A Proverb for My Life$j$, $j${"prompt": "Choose one proverb from Proverbs 3, 15 or 22. Write the proverb, explain its meaning in your own words, and tell how you could use it this week at school, at home or with friends. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: A Proverb for My Life$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Suffering and Trust: Job$j$, $j${"questions": [{"q": "Which of these did Job lose in Job 1?", "options": ["His voice", "His children, his wealth and later his health", "Only his house", "Only his friends"]}, {"q": "What did Job say in Job 1:21?", "options": ["I will go back to Egypt", "The LORD gave, and the LORD hath taken away; blessed be the name of the LORD", "My friends are right", "I will curse God and die"]}, {"q": "What did Job's three friends wrongly believe?", "options": ["That God did not exist", "That suffering always comes from a person's own sin", "That Job was a prophet", "That Job was lazy"]}, {"q": "What hope did Job state in Job 19:25?", "options": ["That his friends would apologize", "That he would be king", "That his money would return", "That his redeemer liveth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Suffering and Trust: Job$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,3}'::int[], array[$j$Job lost his children, his livestock and servants, and then his health.$j$,$j$Job worshipped even in his loss.$j$,$j$The friends insisted Job must have sinned, but God said they had not spoken rightly.$j$,$j$Job said, I know that my redeemer liveth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Suffering and Trust: Job$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: The Prayer Book of Israel: Psalms$j$, $j${"questions": [{"q": "How many psalms are in the book of Psalms?", "options": ["One hundred", "Fifty", "Two hundred", "One hundred and fifty"]}, {"q": "Who wrote about half of the psalms?", "options": ["David", "Solomon", "Moses", "Isaiah"]}, {"q": "What is Hebrew parallelism?", "options": ["A prayer with no words", "Rhyming at the end of lines", "A second line that repeats, completes or contrasts the first", "A list of names"]}, {"q": "According to Psalm 119:105, what is God's word?", "options": ["A river in a dry land", "A rock in the desert", "A sword and a shield", "A lamp unto my feet, and a light unto my path"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: The Prayer Book of Israel: Psalms$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,2,3}'::int[], array[$j$The book of Psalms has 150 psalms.$j$,$j$David wrote about half of the psalms.$j$,$j$Hebrew poetry balances lines in pairs instead of depending on rhyme.$j$,$j$Psalm 119:105 says, Thy word is a lamp unto my feet, and a light unto my path.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: The Prayer Book of Israel: Psalms$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Wisdom for Daily Life: Proverbs$j$, $j${"questions": [{"q": "Who wrote most of the book of Proverbs?", "options": ["Solomon", "Moses", "Isaiah", "Paul"]}, {"q": "What does Proverbs 1:7 say is the beginning of knowledge?", "options": ["Education alone", "Hard work", "Wealth", "The fear of the LORD"]}, {"q": "What does Proverbs 15:1 say turns away wrath?", "options": ["A gift", "A soft answer", "Silence only", "A loud argument"]}, {"q": "A proverb is best understood as:", "options": ["A general truth that is usually right", "A promise that is always right", "A story about a king", "A law for the priests"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Wisdom for Daily Life: Proverbs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,0}'::int[], array[$j$Most of Proverbs was written by Solomon.$j$,$j$The fear of the LORD is the beginning of knowledge.$j$,$j$A soft answer turneth away wrath.$j$,$j$A proverb states a general truth; it is not an unconditional promise.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Wisdom for Daily Life: Proverbs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Seasons and Love: Ecclesiastes and Song of Solomon$j$, $j${"questions": [{"q": "What word does the Preacher use to describe life apart from God?", "options": ["Peace", "Vanity", "Victory", "Joy"]}, {"q": "What does Ecclesiastes 3:1 say there is for every purpose?", "options": ["A test", "A reward", "A season", "A king"]}, {"q": "What is the conclusion of the whole matter in Ecclesiastes 12:13?", "options": ["Avoid all work", "Build great cities", "Gain wealth", "Fear God and keep his commandments"]}, {"q": "What does the Song of Solomon celebrate?", "options": ["Faithful love in marriage", "The temple", "Military victory", "The law of Moses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Seasons and Love: Ecclesiastes and Song of Solomon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,0}'::int[], array[$j$Ecclesiastes says vanity of vanities, a picture of a passing breath.$j$,$j$To every thing there is a season, and a time to every purpose under the heaven.$j$,$j$The whole duty of man is to fear God and keep His commandments.$j$,$j$It is a love poem that celebrates marriage as God's gift.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Seasons and Love: Ecclesiastes and Song of Solomon$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Poetry and Wisdom, Job to Song of Solomon$j$, $j${"questions": [{"q": "Which book asks why good people suffer?", "options": ["Judges", "Job", "Proverbs", "Ruth"]}, {"q": "The book of Psalms is made up of:", "options": ["Letters to churches", "Laws for priests", "Songs and prayers", "Genealogies"]}, {"q": "Which psalm begins, The LORD is my shepherd; I shall not want?", "options": ["Psalm 1", "Psalm 19", "Psalm 100", "Psalm 23"]}, {"q": "What is the theme of Proverbs 1:7?", "options": ["The fear of the LORD is the beginning of knowledge", "A friend loves at all times", "Gold is the greatest good", "Kings must be wise"]}, {"q": "In Ecclesiastes, what does the Preacher say is the whole duty of man?", "options": ["Build wealth", "Study all things", "Fear God and keep his commandments", "Rule well"]}, {"q": "Hebrew poetry is built mainly on:", "options": ["Repeating names", "Balance between lines, called parallelism", "Counting syllables", "Rhyme"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Poetry and Wisdom, Job to Song of Solomon$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,3,0,2,1}'::int[], array[$j$Job wrestles with suffering and God's wisdom.$j$,$j$Psalms is the songbook and prayer book of Israel.$j$,$j$Psalm 23:1 opens with this line.$j$,$j$Proverbs begins with the fear of the LORD as the foundation of wisdom.$j$,$j$Ecclesiastes 12:13 gives this conclusion.$j$,$j$Hebrew poetry balances its lines in pairs.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Poetry and Wisdom, Job to Song of Solomon$j$ on conflict (item_id) do nothing;
